$ErrorActionPreference = 'Stop'

$projectRoot = Split-Path -Parent $PSScriptRoot

function Read-ProjectFile([string]$relativePath) {
    return Get-Content -LiteralPath (Join-Path $projectRoot $relativePath) -Raw
}

function Require-Match([string]$text, [string]$pattern, [string]$message) {
    if ($text -notmatch $pattern) {
        throw $message
    }
}

function Require-NoMatch([string]$text, [string]$pattern, [string]$message) {
    if ($text -match $pattern) {
        throw $message
    }
}

$mergeHost = Read-ProjectFile 'merge_src\PluginPingMerge.cpp'
Require-Match $mergeHost 'case 0: return &m_directItem' 'DIRECT composite row must be item 0.'
Require-Match $mergeHost 'case 1: return &m_proxyItem' 'PROXY composite row must be item 1.'
Require-NoMatch $mergeHost 'case 2:|case 3:' 'The host must see exactly two composite rows.'
Require-Match $mergeHost 'case TMI_NAME:\s+return L"PluginPing"' 'The plugin name must remain PluginPing.'
Require-Match $mergeHost 'instance\.IsReady\(\) \? &instance : nullptr' 'Merged instance readiness guard is missing.'
Require-Match $mergeHost 'm_ping \? m_ping->GetItem\(0\) : nullptr' 'Ping bridge null guard is missing.'

$compositeItem = Read-ProjectFile 'merge_src\CompositeStatusItem.cpp'
$compositeHeader = Read-ProjectFile 'merge_src\CompositeStatusItem.h'
Require-Match $compositeItem 'L"PluginPingLocal"' 'DIRECT must preserve the original PluginPing item ID.'
Require-Match $compositeItem 'L"PluginPingRemote"' 'PROXY must preserve the original PluginPing item ID.'
Require-Match $compositeItem 'ipItem->DrawItem' 'Composite rows must draw their IP section.'
Require-Match $compositeItem 'probeItem->DrawItem' 'Composite rows must draw their TCP/UDP section.'
Require-Match $compositeItem 'MeasureCompositeWidth' 'Composite rows must use the shared section interface.'
Require-Match $compositeItem 'constexpr int kTrailingPadding96\s*=\s*6' 'Composite rows must reserve a stable outer trailing gap.'
Require-Match $compositeItem 'constexpr int kSectionGap96\s*=\s*6' 'Composite rows must define a stable IP/RTT fallback gap.'
Require-Match $compositeItem 'GetTextExtentPoint32W\(dc, L" ", 1, &size\)[\s\S]*?return size\.cx \* 2' 'IP/RTT spacing must use two spaces measured in the host font.'
Require-Match $compositeItem 'ipWidth \+ SectionGap\(dc\) \+ probeWidth \+ ScaledTrailingPadding\(dc\)' 'Section and trailing gaps must be included in the host-facing width.'
Require-Match $compositeItem 'const int contentWidth = w - trailingPadding' 'Child renderers must not paint into the composite trailing gap.'
Require-Match $compositeItem 'x \+ ipWidth \+ sectionGap' 'The compositor must own the blank region between IP and RTT.'
Require-NoMatch $compositeItem 'static_cast<pluginping::CPingStatusItem|static_cast<pluginnetwork::CNetworkStatusItem' 'Composite rows must not cast concrete child item types.'
Require-Match $compositeHeader '(?s)#define WIN32_LEAN_AND_MEAN.*#include <windows\.h>' 'Composite Windows headers must exclude legacy winsock.h.'

