$proxyIpPolicy = Read-ProjectFile 'ping_src\src\ProxyIpStatePolicy.h'
Require-NoMatch ($status + $ipRenderer + $ipWorker) '(?i)latencyMs|latencyDiagnostic|\bonline\b|ProbeHttpLatency|ProbeIcmpLatency' 'IP display still contains latency/online logic.'
Require-Match $ipWorker 'QueryCloudflareTraceIp' 'PROXY must use Cloudflare trace.'
Require-NoMatch $ipWorker 'QueryIpifyIp' 'PROXY fallback must remain removed.'
Require-Match $ipWorker 'SetProxyFailure\(diagnostic, runtime, output, ProxyFailureKind::Transient\)' 'Transient PROXY failures must preserve the last confirmed Cloudflare result.'
Require-Match $ipWorker 'if \(!proxyIdentity\.empty\(\)\)[\s\S]*?const LocalRemoteSnapshot latest[\s\S]*?proxyRawIp == latest\.local\.ipAddress\)[\s\S]*?SetProxyFailure\(proxy\.diagnostic, proxy, remote,[\s\S]*?ProxyFailureKind::RejectedRoute\)' 'Only a confirmed PROXY egress matching DIRECT may clear the identity.'
Require-Match $ipWorker 'proxyInterval = static_cast<unsigned long long>\(\s+\(std::max\)\(cfg\.remoteResolveIntervalMs, 1\)\)' 'PROXY retries must stay on the configured node-switch cadence.'
Require-NoMatch $ipWorker 'proxyInterval[\s\S]{0,160}cfg\.ipFailureBackoffMs' 'PROXY failures must not enter the DIRECT failure backoff.'
Require-Match $proxyIpPolicy 'kind == ProxyFailureKind::Transient && \(!ip\.empty\(\) \|\| displayAsnOnly\)' 'Transient failures must retain an existing confirmed PROXY identity, including loc=CN N/A.'
Require-Match $proxyIpPolicy 'ip\.clear\(\);[\s\S]*?country = L"--"' 'Rejected or initially unavailable PROXY identities must be cleared.'
Require-Match $ipWorker '_wcsicmp\(loc\.c_str\(\), L"CN"\)' 'PROXY loc=CN mapping is missing.'
Require-Match $ipWorker 'runtime\.displayAsnOnly = china;[\s\S]*?runtime\.ip = china \? L"" : ip[\s\S]*?runtime\.country = china \? L"N/A"' 'PROXY loc=CN must collapse ASN and IP to one N/A.'
Require-Match $ipWorker 'if \(!HasDisplayedItem\(\)\)\s+return;' 'Hidden IP rows must not start the worker.'
Require-Match $ipWorker 'EffectiveResolveInterval' 'IP failure backoff is not wired into scheduling.'
Require-Match $ipWorker 'runtime\.failures < cfg\.failThreshold' 'IP failure threshold is not applied.'
Require-Match $ipWorker 'copy = MakeTooltip\(\*snapshot, m_localItem\.LastDrawTick\(\) != 0,' 'IP tooltip must derive from the current snapshot and visible rows.'
Require-NoMatch ($ipWorker + $ipWorkerHeader) 'm_tooltip|m_tooltipMutex' 'The removed IP tooltip cache returned.'
Require-Match $ipWorker 'm_store\.UpdateLocal\(status\)[\s\S]*?m_store\.UpdateRemote\(status\)[\s\S]*?if \(cfg\.debugLog\)[\s\S]*?m_logMutex' 'IP snapshot publication must remain independent from optional log serialization.'
Require-NoMatch ($ipWorker + $ipWorkerHeader) 'm_publishMutex|publishLock' 'The removed IP publication lock returned.'
Require-NoMatch ((Read-ProjectFile 'ping_src\src\ConfigManager.cpp') + (Read-ProjectFile 'ping_src\src\ConfigManager.h') + (Read-ProjectFile 'network_src\src\ConfigManager.cpp') + (Read-ProjectFile 'network_src\src\ConfigManager.h')) 'EnsureLoaded|ReloadIfChanged' 'Removed two-step config reload APIs returned.'
Require-NoMatch ((Read-ProjectFile 'ping_src\src\ConfigManager.cpp') + (Read-ProjectFile 'ping_src\src\ConfigManager.h') + (Read-ProjectFile 'network_src\src\ConfigManager.cpp') + (Read-ProjectFile 'network_src\src\ConfigManager.h')) 'PluginConfig Get\(\) const|unsigned long long Generation\(\) const' 'Removed mutable config-copy and duplicate generation APIs returned.'
Require-Match $ipWorker '!primaryOk && QueryPconlineIp' 'DIRECT fallback must not run after a successful primary query.'
Require-Match $ipWorker 'if \(!primaryOk\)\s+diagnostic \+=' 'DIRECT diagnostics must only describe a fallback that actually ran.'
Require-NoMatch ($status + $ipRenderer + $ipWorker) 'IpDisplayTone|ipTone|primaryOk && fallbackOk' 'Dead split-source warning state returned.'
Require-Match $ipWorker '!proxyRawIp\.empty\(\) && cfg\.localDisplayIp\.empty\(\)[\s\S]{0,240}proxyRawIp == latest\.local\.ipAddress' 'PROXY must reject an egress matching the latest DIRECT baseline using the raw IP.'
Require-Match $ipWorker 'm_directHttpCancellation\.Cancel\(\)[\s\S]*?m_proxyHttpCancellation\.Cancel\(\)[\s\S]*?m_directWorker\.join\(\)[\s\S]*?m_proxyWorker\.join\(\)' 'IP shutdown must cancel both WinHTTP workers before joining.'
Require-Match $ipWorker 'std::thread\(&CPluginPing::DirectWorkerLoop[\s\S]*?std::thread\(&CPluginPing::ProxyWorkerLoop' 'DIRECT and PROXY HTTP requests must run on independent workers.'
Require-Match $ipWorker 'PublishWorkerFailure\(PingEndpoint::Local\)[\s\S]*?WaitForSingleObject\(m_wake, kIpWorkerRetryBackoffMs\)[\s\S]*?PublishWorkerFailure\(PingEndpoint::Remote\)[\s\S]*?WaitForSingleObject\(m_wake, kIpWorkerRetryBackoffMs\)' 'Each IP worker must recover independently with an interruptible retry delay.'
Require-NoMatch ($ipWorker + $ipWorkerHeader) '\bWorkerLoop\b|\bm_started\b|m_workerFailed|m_restartAttempts|m_nextRestartTick|m_startedTick|PublishSnapshot|PublishInitialSnapshot|CPluginPing::OnInitialize' 'The removed IP lifecycle layers returned.'
Require-Match $ipWorker 'awaiting DIRECT revalidation[\s\S]*?proxyIdentity\.clear\(\)' 'A changed PROXY identity must wait for a fresh DIRECT leak baseline before publication.'
Require-Match $ipWorker 'PublishEndpoint\(PingEndpoint::Local, local, cfg\);[\s\S]*?m_directRevalidateCompleted\.store' 'DIRECT revalidation completion must follow publication of the fresh result.'
Require-Match $ipWorker 'pendingRawIp = proxyRawIp;[\s\S]*?m_directRevalidateCompleted\.load\(\) >= pendingRevalidateRequest[\s\S]*?proxyIdentity = pendingIdentity;[\s\S]*?proxyRawIp = pendingRawIp;' 'A completed DIRECT validation must release the already confirmed PROXY identity without another successful trace.'
Require-Match $ipWorker 'RefreshDirect\([\s\S]*?ObserveLocalRouteNow\(\);[\s\S]*?NetworkEpoch\(\) != requestNetworkEpoch' 'DIRECT results crossing a network generation must be discarded.'
Require-Match $ipWorker 'RefreshProxy\([\s\S]*?ObserveLocalRouteNow\(\);[\s\S]*?NetworkEpoch\(\) != requestNetworkEpoch' 'PROXY results crossing a network generation must be discarded.'
Require-Match $ipWorker 'const bool proxyIdentityNeeded =\s+IsRecentlyDisplayed\(m_localItem\.LastDrawTick\(\), cfg, now\) \|\|\s+IsRecentlyDisplayed\(m_remoteItem\.LastDrawTick\(\), cfg, now\)' 'The TCP channel travels the proxy route, so a DIRECT-only layout must still observe node changes.'
Require-Match $ipWorker 'const bool refreshProxy = proxyIdentityNeeded' 'PROXY identity refresh must follow the probe consumers, not only the PROXY row.'
Require-Match $ipWorker 'ProxyFailureKind::RejectedRoute\);[\s\S]*?proxyIdentity = pluginping_shared::MakeDirectLeakIdentity\(proxyRawIp\)' 'A rejected PROXY egress must retain its raw IP while changing route status.'
Require-Match $ipWorker 'routeEpoch\.PublishProxyIdentity\(proxyIdentity\);\s+lastProxy = GetTickCount64\(\)' 'Exactly one proxy identity must be published per refresh, after the rejection verdict.'

$routeEpoch = Read-ProjectFile 'shared_src\RouteEpoch.cpp'
$routeEpochHeader = Read-ProjectFile 'shared_src\RouteEpoch.h'
Require-Match $routeEpoch 'if \(identity\.empty\(\)\)[\s\S]*?return m_epoch\.load' 'An unconfirmed observation must never advance the route epoch.'
Require-Match $routeEpoch 'm_proxyEpoch\.fetch_add\(1' 'Every newly confirmed proxy identity, including the first, must invalidate transports opened before confirmation.'
Require-Match $routeEpoch 'if \(ip\.empty\(\)\)\s+return std::wstring\(\)' 'An identity without an egress IP must fail closed.'
Require-Match $routeEpoch 'GetBestRoute2' 'Local best-route changes must be observed through the Windows route table.'
Require-Match $routeEpoch 'unsigned long long RouteEpoch::ObserveLocalRoute\(\)' 'The bounded local-route observer is missing.'
Require-Match $routeEpochHeader 'MakeDirectLeakIdentity' 'The direct-leak identity helper is missing.'
Require-Match $ipWorker 'identityOut = pluginping_shared::MakeProxyIdentity\(ip\);[\s\S]*?const bool china' 'The node identity must be taken from the raw trace, before the loc=CN display collapse.'

$provider = Read-ProjectFile 'ping_src\src\PublicIpProvider.cpp'
Require-NoMatch ((Read-ProjectFile 'ping_src\src\PublicIpProvider.h') + $provider) 'fallbackUsed' 'NetworkStage already identifies fallback diagnostics; a second flag is redundant.'
Require-Match $provider 'HttpGet\(L"www\.cloudflare\.com", L"/cdn-cgi/trace"' 'Cloudflare trace endpoint changed.'
Require-Match $provider 'const ProxySettings proxy = ResolveProxySettings\(cfg, proxyPolicy\);[\s\S]*?HINTERNET hSession = WinHttpOpen[\s\S]*?WinHttpHandleScope sessionScope\(hSession\);' 'Each public-IP request must own its WinHTTP session lifetime.'
Require-NoMatch $provider 'WinHttpSessionCache|GetSharedHttpSession|class ProxyCache|GetCachedProxySettings' 'Public-IP routing must not stack caches or share evictable sessions across workers.'
Require-Match $provider 'ParseCloudflareTraceBody' 'Cloudflare trace body parser is not shared and testable.'
Require-NoMatch $provider 'QueryIpifyIp|ProbeHttpLatency|ProbeIcmpLatency|ResolveTargetIpv4|MmdbReader' 'Removed IP/latency/Geo code returned.'
Require-Match $provider 'ResolveRoutePlan' 'IP HTTP must consume the shared route plan.'
Require-Match $provider 'class RequestHandleScope' 'IP WinHTTP request handles must use exception-safe ownership.'
Require-Match $provider 'WinHttpOpen\(kPluginPingUserAgent,[\s\S]*?WINHTTP_NO_PROXY_BYPASS' 'PROXY Cloudflare requests must not honor a direct bypass.'
Require-Match $provider 'if \(proxy\.unavailable\)[\s\S]*?return out \+ L" unavailable"' 'Unavailable proxy diagnostics must fail closed before direct-route text.'
Require-Match $provider 'proxyPolicy == EndpointProxyPolicy::ConfiguredProxy[\s\S]*?WINHTTP_DISABLE_KEEP_ALIVE' 'Cloudflare trace must not reuse a tunnel belonging to the previous proxy node.'

$pingConfig = Read-ProjectFile 'ping_src\src\ConfigManager.cpp'
Require-Match $pingConfig 'kIniFileName = L"PluginPing\.ini"' 'IP config must retain the PluginPing name.'
Require-NoMatch $pingConfig '\[Geo\]|PingInterval|RemoteTarget' 'Legacy IP configuration schema returned.'
Require-Match $pingConfig 'L"Style", L"CompactMode"' 'IP rows must read the shared compact mode.'

