Require-Match $networkConfig 'udpEchoServer = L"sg\.falsemeet\.site:3478"' 'UDP echo primary changed.'
Require-Match $networkConfig 'udpFallbackStunServer = L"stun\.cloudflare\.com:3478"' 'UDP STUN fallback changed.'

