Require-Match $networkWorker 'runtime\.targetFailStreak >= 1' 'UDP primary must fall back after its first failed round.'
Require-Match $networkWorker 'kUdpPrimaryRetryIntervalMs = 15000' 'UDP recovery check must be fixed at 15 seconds.'
Require-Match $networkWorker 'kUdpPrimaryRecoverySuccesses = 3' 'UDP recovery must require three consecutive primary successes.'
Require-Match $networkWorker 'primaryRecoverySuccessStreak' 'UDP primary recovery success streak is missing.'
Require-Match $networkWorker 'ChannelIsIdle\(m_udpItem, cfg\) && runtime\.targetIndex == 0' 'UDP fallback recovery must bypass idle backoff.'
