Require-Match $networkWorker 'if \(m_tcpItem\.LastDrawTick\(\) == 0\)' 'Hidden TCP channel must not probe.'
Require-Match $networkWorker 'if \(m_udpItem\.LastDrawTick\(\) == 0\)' 'Hidden UDP channel must not probe.'
Require-Match $networkWorker 'fallbackVerified' 'UDP fallback verification state is missing.'
Require-Match $networkWorker 'fallbackAttempted' 'UDP fallback attempt state is missing.'
Require-Match $networkWorker 'onFallback && !runtime\.fallbackAttempted' 'Untried fallback must remain pending.'
Require-NoMatch $networkWorker 'PushQualityFailure' 'Primary Echo recovery must not contaminate the active STUN quality window.'
Require-Match $networkWorker 'ResetRuntime\(runtime, capacity, enabled, idle, targetKey\);\s+m_tcpProbe\.ResetTransport\(\);' 'TCP lifecycle changes must drop stale pooled transport.'
Require-Match $networkWorker 'ResetRuntime\(runtime, capacity, enabled, idle, targetKey\);\s+m_udpProbe\.ResetTransport\(\);' 'UDP lifecycle changes must drop stale socket transport.'
Require-Match $networkWorker 'ObserveLocalRoute' 'Probe workers must observe local route generation changes.'
Require-Match $networkWorker 'NetworkEpoch\(\)' 'Probe target keys must fold in the local network generation.'
Require-Match $networkWorker 'ProxyEpoch\(\)' 'TCP target keys must fold in the proxy identity generation.'
Require-Match (Read-ProjectFile 'shared_src\RoutePlan.cpp') 'shareProxyIdentityForUdp[\s\S]*?UdpRoute::Socks5' 'Split HTTP/SOCKS routes need an explicit same-upstream identity declaration.'
Require-Match $networkWorker 'ChannelTargetKey\(targets, proxyRoute, ChannelKind::Tcp\)[\s\S]*?ChannelTargetKey\(targets, proxyRoute, ChannelKind::Udp\)' 'TCP and UDP workers must derive channel-specific target keys.'
Require-Match $networkWorker 'idle && item\.ActivityEvent\(\)[\s\S]*?WaitForMultipleObjects' 'Idle waits must be event-driven and wake when the row becomes visible.'
Require-Match $networkWorker 'if \(routeChangedEvent && \(!idle \|\| item\.ActivityEvent\(\)\)\)' 'A missing row-activity event must fall back to bounded polling while idle.'
