Require-Match $networkWorker 'NotifyRouteChange2' 'Windows route-table change notification registration is missing.'
Require-Match $networkWorker 'NotifyUnicastIpAddressChange' 'Windows source-address change notification registration is missing.'
Require-Match $networkWorker 'm_running\.store\(true[\s\S]*?m_tcpWorker = std::thread\(&CPluginNetwork::TcpWorkerLoop[\s\S]*?m_udpWorker = std::thread\(&CPluginNetwork::UdpWorkerLoop' 'Network workers must enter the running state before creating both member threads.'
Require-Match $networkWorker 'm_tcpProbe\.Cancel\(\)[\s\S]*?m_udpProbe\.Cancel\(\)[\s\S]*?m_primaryEchoProbe\.Cancel\(\)[\s\S]*?m_tcpWorker\.join\(\)[\s\S]*?m_udpWorker\.join\(\)' 'Network shutdown must cancel probes before joining both member workers.'
Require-NoMatch $networkWorker 'std::thread tcp|std::thread udp|std::move\(tcp\)|std::move\(udp\)|lock\.unlock\(\)|lock\.lock\(\)' 'The removed Network thread handoff layer returned.'
Require-NoMatch ($networkWorker + (Read-ProjectFile 'network_src\src\PluginNetwork.h')) 'm_started|WaitForActivation|runtime\.startTick|runtime\.initialized|TcpFallbackPolicy|UdpFallbackPolicy|IsAuthoritativeTcpTarget|DecideAfterProbe|DecideAfterPrimaryValidation' 'Removed Network lifecycle and one-line policy layers returned.'
Require-NoMatch ((Read-ProjectFile 'network_src\src\SlidingWindow.h') + $networkWorker) 'SlidingWindow\(\) \{ Resize\(30\); \}|int WindowCapacity\(const PluginConfig&' 'Removed eager window allocation or duplicate capacity formula returned.'
Require-NoMatch ($mergeHost + (Read-ProjectFile 'merge_src\PluginPingMerge.h')) 'CPluginPingMerge::Ping\(\)|CPluginPingMerge::Network\(\)|CPluginPingMerge::OnInitialize' 'Removed no-op merged forwarding methods returned.'
Require-Match $networkWorker 'InvalidateLocalRoute[\s\S]*?routeChangedEvent[\s\S]*?WaitForMultipleObjects' 'Idle waits must wake promptly when Windows reports an interface change.'
Require-Match $networkWorker 'if \(routeChangedEvent && \(!idle \|\| item\.ActivityEvent\(\)\)\)[\s\S]*?for \(;;\)[\s\S]*?static_cast<unsigned long long>\(1000\)[\s\S]*?item\.ActivityEvent\(\)' 'Notification or activity-event failure must retain interruptible one-second route polling.'
Require-Match (Read-ProjectFile 'network_src\src\NetworkStatusItem.cpp') 'm_lastDrawTick\.exchange\(now\)[\s\S]*?SetEvent\(m_activityEvent\)' 'A newly visible row must wake its idle worker.'
Require-Match $networkWorker 'copy = MakeTooltip\(\*snapshot, m_tcpItem\.LastDrawTick\(\) != 0,' 'Network tooltip must derive from the current snapshot and visible rows.'
Require-NoMatch ($networkWorker + (Read-ProjectFile 'network_src\src\PluginNetwork.h')) 'm_tooltip|m_tooltipMutex|RebuildTooltip|PublishInitialSnapshot|CPluginNetwork::OnInitialize' 'The removed Network cache and initialization layers returned.'
Require-Match $networkWorker 'const bool routeChanged = !runtime\.targetSetKey\.empty\(\) &&\s+runtime\.targetSetKey != targetKey;' 'A route change must be distinguished from a first round before the reset clears it.'
Require-Match $networkWorker 'runtime\.lastDiagnostic \+= L"; transport rebuilt after route change";[\s\S]*?runtime\.lastDiagnostic \+= L"; transport rebuilt after route change";' 'Both workers must report a rebuild where the probe result cannot clobber it.'
Require-Match $networkWorker 'route changed; rebuilding TCP transport[\s\S]*?route changed; rebuilding UDP transport' 'Both channels must publish an empty RTT window as soon as their route key changes.'
Require-Match $networkWorker 'ProbeGenerationChanged' 'Results crossing a route generation must be discarded.'
Require-Match $networkWorker 'UDP egress changed, transport rebuilt";\s+break;[\s\S]*?runtime\.window\.Push' 'A changed STUN egress must rebuild the UDP transport without pushing the transition result into the new window.'
Require-Match $networkWorker 'proxy node: [\s\S]*?epoch ' 'The debug log must record which node a measurement belongs to.'
Require-Match (Read-ProjectFile 'network_src\src\ChannelStatePolicy.h') 'fallbackPending' 'Channel state policy must model fallback warming explicitly.'
Require-Match (Read-ProjectFile 'network_src\src\ChannelStatePolicy.h') 'successCount == 0' 'Unsupported must be based on the current window.'
Require-Match $networkWorker 'void CPluginNetwork::TcpWorkerLoop\(\)[\s\S]*?while \(m_running\.load[\s\S]*?HandleWorkerFailure\(ChannelKind::Tcp\);[\s\S]*?WaitForSingleObject\(m_wake, kWorkerRetryBackoffMs\)' 'The TCP worker must keep retrying with an interruptible backoff while the plugin is running.'
Require-Match $networkWorker 'void CPluginNetwork::UdpWorkerLoop\(\)[\s\S]*?while \(m_running\.load[\s\S]*?HandleWorkerFailure\(ChannelKind::Udp\);[\s\S]*?WaitForSingleObject\(m_wake, kWorkerRetryBackoffMs\)' 'The UDP worker must keep retrying with an interruptible backoff while the plugin is running.'
Require-NoMatch $networkWorker 'kMaxWorkerRestarts|attempt \+ 1' 'A retry cap can leave m_running true after a channel worker exits permanently.'

$networkLoader = Read-ProjectFile 'network_src\src\ConfigManager.cpp'
Require-Match $networkLoader 'c\.tcpTargetUrl = L"https://www\.google\.com/generate_204"' 'Google must remain authoritative for TCP.'
Require-Match $networkLoader 'kIniFileName = L"PluginPing\.ini"' 'Network config must retain the PluginPing name.'
Require-NoMatch $networkLoader 'pluginnetwork\.ini|kLegacyIniFileName|NormalizeIniFileNameCase' 'Legacy network config migration returned.'

$udpProbe = Read-ProjectFile 'network_src\src\StunProbe.cpp'
Require-Match $udpProbe 'size != requestSize \|\| memcmp\(message, request, requestSize\) != 0' 'UDP echo must validate an exact echoed payload.'
Require-Match $udpProbe 'void UdpProbe::ResetTransport\(\)[\s\S]*?m_resolved = false;[\s\S]*?m_lastResolveTick = 0;' 'A transport reset must drop the address cached under the previous route.'
Require-Match (Read-ProjectFile 'network_src\src\StunProbe.h') 'class UdpProbe' 'UDP transport still exposes the obsolete STUN-only class name.'

$project = Read-ProjectFile 'PluginPing.vcxproj'
Require-Match $project 'PLUGINPING_MERGED' 'Child export suppression is missing.'
Require-Match $project 'ping_ConfigManager\.obj' 'Ping object names are not isolated.'
Require-Match $project 'network_ConfigManager\.obj' 'Network object names are not isolated.'
Require-Match $project '<TargetName>PluginPing</TargetName>' 'The DLL target must be PluginPing.'
Require-Match $project '<None Include="PluginPing\.ini">' 'PluginPing.ini is not deployed.'
Require-Match $project 'merge_src\\CompositeStatusItem\.cpp' 'Composite row source is missing from the project.'
Require-Match $project 'shared_src\\RoutePlan\.cpp' 'Shared route plan source is missing from the project.'
Require-Match $project 'shared_src\\RouteEpoch\.cpp' 'Shared route epoch source is missing from the project.'
Require-Match $project 'shared_src\\HostDrawing\.h' 'Shared host drawing state is missing from the project.'
Require-NoMatch $project 'pluginnetwork\.ini|MmdbReader|network_src\\include' 'Old config, MMDB, or duplicate include tree remains in the project.'

