$networkItem = Read-ProjectFile 'network_src\src\NetworkStatusItem.cpp'
$networkRenderer = Read-ProjectFile 'network_src\src\Renderer.cpp'
$metricsData = Read-ProjectFile 'network_src\src\MetricsData.h'
$hostDrawing = Read-ProjectFile 'shared_src\HostDrawing.h'
Require-Match $ipItem 'MarkDisplayed\(\)' 'IP visibility signal is missing.'
