Require-Match $ipItem 'const int candidate = measured;' 'Composite IP width must not include the standalone Width floor.'
Require-NoMatch $ipRenderer '\bipPad\b' 'IP/probe spacing must not reintroduce a second tail padding term.'
Require-Match $ipRenderer 'm\.gap\s*=\s*\(std::max\)\(1, TextWidth\(dc, L" "\)\)' 'IP group internals must use one measured host-font space.'
Require-Match $ipRenderer 'displayAsnOnly' 'PROXY loc=CN must suppress the second IP placeholder.'
Require-NoMatch $ipRenderer '\brightPad\b' 'IP renderer must not own the composite section gap.'
Require-Match $networkRenderer 'if \(showLabel\)' 'Embedded TCP/UDP labels are not suppressible.'
