Require-Match $metricsData 'ToneForLatencyValue[\s\S]*?valueMs <= 70[\s\S]*?QualityTone::Good[\s\S]*?valueMs <= 149[\s\S]*?QualityTone::Warn[\s\S]*?QualityTone::Bad' 'RTT and JIT must share the PluginPing 70/150 ms colour boundaries.'
Require-Match $networkRenderer 'baselineRttCell\s*=\s*TextWidth\(dc, cfg\.compactMode \? L"999" : L"999 ms"\)' 'RTT must reserve one native-style value-and-unit cell.'
Require-Match $networkRenderer 'layout\.rttCell\s*=\s*\(std::max\)\(measuredRttCell, baselineRttCell\)' 'RTT cell must use its stable baseline width.'
Require-Match $networkRenderer 'layout\.jitterValue\s*=\s*\(std::max\)\(measuredJitter, baselineJitter\)' 'Jitter column must reserve its three-digit baseline width.'
Require-Match $networkRenderer 'baselineJitter\s*=\s*TextWidth\(dc, L"999"\)' 'Jitter column must remain stable throughout the 1-999 ms range.'
Require-Match $metricsData 'if \(valueMs < 0\)[\s\S]*?QualityTone::Neutral' 'An unavailable RTT or JIT value must remain neutral.'
Require-Match $networkRenderer 'DrawTextIn\(hDC, latency,[\s\S]*?DrawTextIn\(hDC, L"ms",[\s\S]*?DrawTextIn\(hDC, L"JIT:"' 'The RTT unit must precede the JIT field.'
Require-Match $networkRenderer 'cursor = rttCellLeft \+ layout\.rttCell \+ layout\.fieldGap' 'JIT must use a fixed row-aligned cell origin.'
Require-NoMatch ($networkRenderer + $networkItem + $networkWorker) '(?-i:\bJit\b)' 'Visible jitter labels must use JIT casing consistently.'
Require-Match $networkRenderer 'ComputeColumns\(hDC, hostFont\.handle, hostFont\.handle, metrics,[\s\S]*?showLabel, kind, false\)' 'DIRECT and PROXY must draw with shared probe column widths.'
Require-Match $networkRenderer 'if \(!showLabel\)[\s\S]*?metrics\.leftPad = 0;[\s\S]*?metrics\.rightPad = 0;' 'Embedded probe padding must be removed.'
Require-NoMatch $networkRenderer 'PercentText|layout\.percent|L"100%"|L"--%"' 'Inline stability percentage must remain removed.'
Require-NoMatch $networkRenderer 'FillCircle|Ellipse|CircleEntry|showStatusDot|plusMinus|L"\\u00B1"' 'The obsolete status dot or plus/minus layout returned.'
Require-NoMatch ($ipItem + $networkItem) 'GetItemValueText\(\) const\s*\{\s*return nullptr' 'Custom text getters must never return null.'
Require-Match $networkLoader 'written == expected' 'Default INI writes must reject short writes.'

$ini = Read-ProjectFile 'PluginPing.ini'
Require-Match $ini '\[IP\][\s\S]*DirectResolveIntervalMs=10000' 'Merged INI is missing IP settings.'
Require-Match $ini '\[IP\][\s\S]*ProxyResolveIntervalMs=1000' 'Merged INI is missing fast PROXY refresh settings.'
Require-Match $ini 'ConfigVersion=2' 'Merged INI must opt out of the legacy 5-second default migration.'
Require-Match $ini 'ShareProxyIdentityForUdp=false' 'Merged INI must expose the explicit split-proxy identity policy.'
Require-Match $ini '\[Style\][\s\S]*Typography follows TrafficMonitor' 'Host-owned typography is not documented in the INI.'
Require-NoMatch ($pingConfig + $networkConfig + $networkLoader + $ipRenderer + $networkRenderer + $ini) 'FontName|FontSize|fontName|fontSize' 'A second plugin-owned typography source returned.'
Require-NoMatch ($networkConfig + $networkLoader + $networkItem + $networkRenderer + $ini) 'ShowStatusDot|showStatusDot' 'Removed status-dot configuration returned.'
Require-Match $ini 'PluginPing 1\.0\.14' 'Bundled INI version must match the merged product.'

$versionResource = Read-ProjectFile 'merge_src\PluginPing.rc'
$pingVersionResource = Read-ProjectFile 'ping_src\src\PluginPing.rc'
$networkVersionResource = Read-ProjectFile 'network_src\src\PluginNetwork.rc'
$pingCommon = Read-ProjectFile 'ping_src\src\Common.h'
$networkCommon = Read-ProjectFile 'network_src\src\Common.h'
Require-Match $mergeHost 'case TMI_VERSION:\s+return L"1\.0\.14"' 'Host-reported version must be 1.0.14.'
Require-Match $versionResource 'FILEVERSION\s+1,0,14,0' 'Windows file version must be 1.0.14.0.'
Require-Match $versionResource 'VALUE "FileVersion", "1\.0\.14"' 'Windows version string must be 1.0.14.'
Require-Match $pingVersionResource 'FILEVERSION\s+1,0,14,0' 'IP child file version drifted.'
Require-Match $networkVersionResource 'FILEVERSION\s+1,0,14,0' 'Network child file version drifted.'
Require-Match $pingCommon 'kPluginPingVersion\[\]\s*=\s*L"1\.0\.14"' 'IP host version drifted.'
Require-Match $networkCommon 'kPluginNetworkVersion\[\]\s*=\s*L"1\.0\.14"' 'Network host version drifted.'
Require-Match $pingCommon 'kPluginPingUserAgent\[\]\s*=\s*L"PluginPing/1\.0\.14"' 'IP User-Agent version drifted.'
Require-Match $networkCommon 'kPluginNetworkUserAgent\[\]\s*=\s*L"PluginPing/1\.0\.14"' 'TCP User-Agent version drifted.'
Require-Match $pingCommon '(?s)#include <winsock2\.h>.*#include <windows\.h>' 'IP headers must include Winsock2 before Windows.'
Require-NoMatch $pingCommon 'ipexport|icmpapi|iphlpapi' 'Removed ICMP dependencies must not return.'

$routePlan = Read-ProjectFile 'shared_src\RoutePlan.cpp'
Require-Match $routePlan 'Auto deliberately follows only an enabled static user proxy' 'Auto route semantics are not documented in code.'
Require-Match $routePlan 'HttpRoute::Unavailable' 'Proxy routes must fail closed when unusable.'
Require-Match $routePlan 'ResolveRoutePlan' 'HTTP/TCP/UDP route resolution is not shared.'
Require-Match $routePlan 'SharesNamedProxyEndpoint' 'HTTP and UDP must share proxy identity only when their normalized endpoints match.'

Write-Output 'PluginPing composite contract checks passed.'
